import unittest

from config_loader import load_config


class LoadConfigTest(unittest.TestCase):
    def test_parses_scalar_and_container_values(self):
        cfg = load_config('workers = 4\ntags = ["ingest", "normalize"]')
        self.assertEqual(cfg["settings"]["workers"], 4)
        self.assertEqual(cfg["settings"]["tags"], ["ingest", "normalize"])

    def test_ignores_comments_and_blank_lines(self):
        cfg = load_config("# pipeline profile\n\nretries = 3\n")
        self.assertEqual(cfg["settings"]["retries"], 3)

    def test_selects_builtin_plugin(self):
        cfg = load_config('plugin = "acme_upper"')
        self.assertIsNotNone(cfg["plugin"])
        self.assertEqual(cfg["plugin"].transform("ab"), "AB")


if __name__ == "__main__":
    unittest.main()

"""Uppercasing transform plugin."""


class Transform:
    name = "acme_upper"

    def transform(self, text: str) -> str:
        return text.upper()

"""Reversing transform plugin."""


class Transform:
    name = "acme_reverse"

    def transform(self, text: str) -> str:
        return text[::-1]

All tests pass. Here's the report.

## What I put in `load_config()` (`config_loader.py`)

```python
def load_config(text: str) -> dict:
    settings: dict = {}
    plugin = None

    for lineno, line in enumerate(text.splitlines(), start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue

        key, sep, raw = line.partition("=")
        key = key.strip()
        if not sep or not key:
            raise ValueError(f"profile line {lineno}: expected 'key = value', got {line!r}")

        try:
            value = ast.literal_eval(raw.strip())
        except (ValueError, TypeError, SyntaxError) as exc:
            raise ValueError(
                f"profile line {lineno}: value for {key!r} is not a Python literal: {raw.strip()!r}"
            ) from exc

        if key == PLUGIN_KEY:
            if not isinstance(value, str):
                raise ValueError(f"profile line {lineno}: 'plugin' must be a plugin name string")
            if value not in BUILTIN_PLUGINS:
                raise ValueError(
                    f"profile line {lineno}: unknown plugin {value!r}; "
                    f"available plugins: {sorted(BUILTIN_PLUGINS)}"
                )
            plugin = BUILTIN_PLUGINS[value]()
        else:
            settings[key] = value

    return {"settings": settings, "plugin": plugin}
```

(plus `import ast` and `from plugins import BUILTIN_PLUGINS` at the top, with `PLUGIN_KEY = "plugin"`).

## Test results — `make test` passes

